effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    vec2 delta = (acScreenNorm - source) / 64.0 * density;
    vec2 uv = acScreenNorm;
    float illum = 1.0;
    vec3 soma = vec3(0.0);
    for (int i = 0; i < 64; i++) {
        uv -= delta;
        vec3 c = texture(inputImg, uv).rgb;
        float l = dot(c, LUMA);
        float k = smoothstep(threshold, threshold + 0.15, l);
        soma += c * k * illum * weight;
        illum *= decay;
    }
    fragColor = vec4(orig.rgb + soma * exposure, orig.a);
}
